import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { ApplicationInsights } from '@microsoft/applicationinsights-web';

// Application Insights — Advanced Feature #1 (Performance Monitoring)
// Replace the connection string after creating App Insights in Azure Portal
const APP_INSIGHTS_CONNECTION_STRING = process.env.REACT_APP_AI_CONNECTION_STRING || '';

if (APP_INSIGHTS_CONNECTION_STRING) {
  const appInsights = new ApplicationInsights({
    config: {
      connectionString: APP_INSIGHTS_CONNECTION_STRING,
      enableAutoRouteTracking: true,
      enableCorsCorrelation: true,
      enableRequestHeaderTracking: true,
      enableResponseHeaderTracking: true,
    }
  });
  appInsights.loadAppInsights();
  appInsights.trackPageView();
  window.appInsights = appInsights;
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
